components.css:
.ds-card { position: relative; background: var(--surface, #fff); border: 1px solid var(--line, #dbe3ed); border-radius: 14px; box-shadow: 0 1px 2px rgba(16,28,46,.05), 0 2px 8px rgba(16,28,46,.05); padding: 28px 32px; transition: transform .25s ease, box-shadow .25s ease, border-color .25s ease; }
.ds-card:hover { transform: translateY(-4px); border-color: color-mix(in srgb, var(--primary, #06a6d6) 45%, var(--line, #dbe3ed)); box-shadow: 0 2px 6px rgba(16,28,46,.06), 0 12px 32px rgba(16,28,46,.1), 0 8px 28px rgba(6,166,214,.18); }
.ds-card::before, .ds-card::after { content: ''; position: absolute; width: 16px; height: 16px; opacity: 0; transition: opacity .25s ease; pointer-events: none; }
.ds-card::before { top: -1px; left: -1px; border-top: 2px solid var(--primary, #06a6d6); border-left: 2px solid var(--primary, #06a6d6); border-top-left-radius: 14px; }
.ds-card::after { bottom: -1px; right: -1px; border-bottom: 2px solid var(--primary-2, #7c5cff); border-right: 2px solid var(--primary-2, #7c5cff); border-bottom-right-radius: 14px; }
.ds-card:hover::before, .ds-card:hover::after { opacity: 1; }
.ds-card-title { margin: 0 0 10px; font-size: 18px; font-weight: 700; color: var(--text, #101c2e); }
.ds-card-body { margin: 0; font-size: 14px; line-height: 1.7; color: var(--muted, #5b6b80); }

.ds-btn-primary { font-family: ui-monospace, 'SF Mono', 'JetBrains Mono', 'Fira Code', Menlo, Consolas, monospace; font-size: 14px; font-weight: 600; padding: 11px 24px; border: none; border-radius: 10px; cursor: pointer; background: var(--primary, #06a6d6); color: #041018; box-shadow: 0 8px 28px rgba(6,166,214,.18); transition: transform .2s ease, box-shadow .2s ease; }
.ds-btn-primary:hover { transform: translateY(-2px); box-shadow: 0 8px 28px rgba(6,166,214,.18), 0 2px 6px rgba(16,28,46,.06), 0 12px 32px rgba(16,28,46,.1); }
.ds-btn-primary:focus-visible { outline: 2px solid var(--primary-2, #7c5cff); outline-offset: 2px; }

.ds-btn-ghost { font-family: ui-monospace, 'SF Mono', 'JetBrains Mono', 'Fira Code', Menlo, Consolas, monospace; font-size: 14px; font-weight: 600; padding: 11px 24px; border-radius: 10px; cursor: pointer; background: var(--surface, #fff); color: var(--muted, #5b6b80); border: 1px solid var(--line, #dbe3ed); transition: transform .2s ease, color .2s ease, border-color .2s ease; }
.ds-btn-ghost:hover { transform: translateY(-2px); color: var(--primary, #06a6d6); border-color: var(--primary, #06a6d6); }
.ds-btn-ghost:focus-visible { outline: 2px solid var(--primary, #06a6d6); outline-offset: 2px; }

.ds-chip { font-family: ui-monospace, 'SF Mono', 'JetBrains Mono', 'Fira Code', Menlo, Consolas, monospace; font-size: 12px; padding: 2px 10px; border-radius: 6px; white-space: nowrap; border: 1px solid transparent; display: inline-block; }
.ds-chip-tech { color: var(--primary, #06a6d6); background: color-mix(in srgb, var(--primary, #06a6d6) 12%, transparent); border-color: color-mix(in srgb, var(--primary, #06a6d6) 30%, transparent); }
.ds-chip-reading { color: var(--primary-2, #7c5cff); background: color-mix(in srgb, var(--primary-2, #7c5cff) 12%, transparent); border-color: color-mix(in srgb, var(--primary-2, #7c5cff) 30%, transparent); }
.ds-chip-calligraphy { color: var(--calligraphy, #d97a1f); background: color-mix(in srgb, var(--calligraphy, #d97a1f) 12%, transparent); border-color: color-mix(in srgb, var(--calligraphy, #d97a1f) 30%, transparent); }

.ds-nav { display: flex; gap: 2px; }
.ds-nav-link { position: relative; text-decoration: none; color: var(--muted, #5b6b80); font-size: 14px; padding: 8px 13px; border-radius: 9px; transition: color .2s ease, background-color .2s ease; }
.ds-nav-link:hover { color: var(--text, #101c2e); background: var(--surface-2, #e9eef5); }
.ds-nav-active { color: var(--primary, #06a6d6); background: color-mix(in srgb, var(--primary, #06a6d6) 10%, transparent); }
.ds-nav-active::after { content: ''; position: absolute; left: 14px; right: 14px; bottom: 1px; height: 2px; border-radius: 1px; background: linear-gradient(90deg, var(--primary, #06a6d6), var(--primary-2, #7c5cff)); box-shadow: 0 0 8px var(--primary, #06a6d6); }
.ds-cmd { font-family: ui-monospace, 'SF Mono', 'JetBrains Mono', 'Fira Code', Menlo, Consolas, monospace; font-size: 11px; color: var(--faint, #93a1b3); margin-right: 5px; }

.ds-term { background: var(--surface, #fff); border: 1px solid var(--line, #dbe3ed); border-radius: 14px; box-shadow: 0 1px 2px rgba(16,28,46,.05), 0 2px 8px rgba(16,28,46,.05); overflow: hidden; }
.ds-term-head { display: flex; align-items: center; gap: 7px; padding: 12px 16px; border-bottom: 1px solid var(--line, #dbe3ed); }
.ds-dot { width: 11px; height: 11px; border-radius: 50%; }
.ds-dot-red { background: #ff5f57; }
.ds-dot-yellow { background: #febc2e; }
.ds-dot-green { background: #28c840; }
.ds-term-title { font-family: ui-monospace, 'SF Mono', 'JetBrains Mono', 'Fira Code', Menlo, Consolas, monospace; font-size: 12px; color: var(--faint, #93a1b3); margin-left: 6px; letter-spacing: .3px; }
.ds-term-body { padding: 18px 20px; }
.ds-line { font-family: ui-monospace, 'SF Mono', 'JetBrains Mono', 'Fira Code', Menlo, Consolas, monospace; font-size: 13.5px; line-height: 1.9; color: var(--text, #101c2e); letter-spacing: .3px; }
.ds-cmdline { color: var(--primary, #06a6d6); }
